package com.scriptles.cabinet.catalog.entity;
import com.scriptles.cabinet.catalog.franchise.FranchiseMediaRelationType; import com.scriptles.cabinet.media.entity.Media; import com.scriptles.cabinet.media.enums.ExternalSource; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="collection_items",uniqueConstraints=@UniqueConstraint(name="uk_collection_item_media",columnNames={"collection_id","media_id"})) @Getter @Setter @NoArgsConstructor
public class CollectionItem { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="collection_id",nullable=false) private Collection collection; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="section_id") private CollectionSection section; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="media_id",nullable=false) private Media media; @Column(nullable=false) private int position; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private FranchiseMediaRelationType relationType=FranchiseMediaRelationType.CORE; @Column(nullable=false) private boolean sourceManaged; @Enumerated(EnumType.STRING) @Column(length=30) private ExternalSource sourceProvider; private Instant createdAt; private Instant updatedAt; }
